72	export async function loadUnits(): Promise<InventoryUnit[]> {
73	  const base = await readJson("units.json", z.array(InventoryUnitSchema));
74	  // Merge per-unit detail-page enrichment (daysOnLot, vin, more accurate
75	  // colors, MSRP overrides). Generated by scripts/enrich_units_from_listings.py.
76	  // Optional: app runs fine without it.
77	  let enrichment: Record<string, Partial<InventoryUnit>> = {};
78	  try {
79	    const raw = await fs.readFile(path.join(DATA_DIR, "units-enrichment.json"), "utf8");
80	    enrichment = JSON.parse(raw) as Record<string, Partial<InventoryUnit>>;
81	  } catch (err) {
82	    if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") throw err;
83	  }
84	  return base.map((u) => {
85	    const e = enrichment[u.id];
86	    if (!e) return u;
87	    // Only allow whitelisted fields to override — never let an enrichment
88	    // file silently change model/year/trim/dealerId.
89	    return {
90	      ...u,
91	      daysOnLot: e.daysOnLot ?? u.daysOnLot,
92	      vin: e.vin ?? u.vin,
93	      msrp: e.msrp ?? u.msrp,
94	      exteriorColor: e.exteriorColor ?? u.exteriorColor,
95	      interiorColor: e.interiorColor ?? u.interiorColor,
96	    };
97	  });
98	}
