140	// Trims that skew MSRP comparisons because they're priced as halo/performance
141	// variants ($15-25k above the long-range floor). Used to compute a fairer
142	// retention denominator for typical-buyer comparisons.
143	const HALO_TRIM_REGEX = /\b(GT|N|Performance|Calligraphy)\b/i;
144	
145	// Per-model used-market summary used as new-car negotiation leverage data.
146	// retentionPercent = median used / lowest new MSRP. Lower = steeper
147	// depreciation = stronger lever when arguing a new-car discount.
148	//
149	// includeHaloTrims controls whether GT / N / Performance / Calligraphy trims
150	// are eligible to set the new-MSRP floor. Default false because those trims
151	// are usually not what the buyer is shopping and they tank the retention
152	// number to the point of being meaningless.
153	export function computeUsedMarketStats(
154	  used: UsedListing[],
155	  specs: Spec[],
156	  includeHaloTrims = false,
157	): UsedMarketStat[] {
158	  const median = (arr: number[]): number => {
159	    if (!arr.length) return 0;
160	    const sorted = [...arr].sort((a, b) => a - b);
161	    const mid = Math.floor(sorted.length / 2);
162	    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
163	  };
164	  const newMsrpByModel = new Map<string, number>();
165	  for (const s of specs) {
166	    if (!s.msrpCad) continue;
167	    if (!includeHaloTrims && HALO_TRIM_REGEX.test(s.trim)) continue;
168	    const cur = newMsrpByModel.get(s.model);
169	    if (cur == null || s.msrpCad < cur) newMsrpByModel.set(s.model, s.msrpCad);
170	  }
171	  return MODELS.map((model) => {
172	    const rows = used.filter((u) => u.model === model);
173	    const prices = rows.map((u) => u.priceCad);
174	    const kms = rows.map((u) => u.kmDriven);
175	    const medPrice = median(prices);
176	    const newFloor = newMsrpByModel.get(model) ?? null;
177	    return {
178	      model,
179	      count: rows.length,
180	      medianPriceCad: medPrice,
181	      minPriceCad: prices.length ? Math.min(...prices) : 0,
182	      maxPriceCad: prices.length ? Math.max(...prices) : 0,
183	      medianKm: median(kms),
184	      newMsrpFloorCad: newFloor,
185	      retentionPercent: newFloor && medPrice ? Math.round((medPrice / newFloor) * 100) : null,
186	    };
187	  }).filter((s) => s.count > 0);
188	}
