190	export function specKey(model: string, year: number, trim: string, drivetrain: string): string {
191	  return `${model}|${year}|${trim}|${drivetrain}`;
192	}
193	
194	export function specMap(specs: Spec[]): Map<string, Spec> {
195	  return new Map(specs.map((s) => [specKey(s.model, s.year, s.trim, s.drivetrain), s]));
196	}
