225	export async function listSnapshotFiles(): Promise<string[]> {
226	  const dir = path.join(DATA_DIR, "snapshots");
227	  try {
228	    const entries = await fs.readdir(dir);
229	    return entries
230	      .filter((e) => e.endsWith(".json"))
231	      .sort();
232	  } catch {
233	    return [];
234	  }
235	}
236	
237	export async function loadSnapshots(limit?: number): Promise<Snapshot[]> {
238	  const files = await listSnapshotFiles();
239	  const slice = limit ? files.slice(-limit) : files;
240	  return Promise.all(
241	    slice.map((f) =>
242	      readJson(path.join("snapshots", f), SnapshotSchema),
243	    ),
244	  );
245	}
