247	// Consolidated dataset: every unit decorated with OTD, deal score, and the
248	// incentives that apply. This is the single source of truth all UI reads from.
249	//
250	// buyerProvince controls the sales-tax basis + transport-cost line. When
251	// omitted (e.g. older callers), each unit's OTD assumes the buyer is in
252	// the dealer's province — the legacy pre-2026-05 behavior.
253	export async function loadScoredUnits(buyerProvince?: import("./constants").Province): Promise<{
254	  units: ScoredUnit[];
255	  dealers: Dealer[];
256	  dealerById: Map<string, Dealer>;
257	  incentives: Incentive[];
258	  buyerProvince: import("./constants").Province | null;
259	}> {
260	  const [units, dealers, incentives] = await Promise.all([
261	    loadUnits(),
262	    loadDealers(),
263	    loadIncentives(),
264	  ]);
265	  const dealerById = new Map(dealers.map((d) => [d.id, d]));
266	  const unitsByDealer = new Map<string, InventoryUnit[]>();
267	  for (const u of units) {
268	    const arr = unitsByDealer.get(u.dealerId) ?? [];
269	    arr.push(u);
270	    unitsByDealer.set(u.dealerId, arr);
271	  }
272	
273	  const scored = units.map((unit) => {
274	    const dealer = dealerById.get(unit.dealerId);
275	    if (!dealer) {
276	      throw new Error(`Unit ${unit.id} references unknown dealer ${unit.dealerId}`);
277	    }
278	    const applicable = applicableIncentives(unit, dealer, incentives);
279	    const otdBreakdown = computeOtd(unit, dealer, applicable, buyerProvince);
280	    const { score, breakdown } = computeDealScore({
281	      unit,
282	      dealer,
283	      dealerUnits: unitsByDealer.get(dealer.id) ?? [],
284	      applicable,
285	    });
286	    return {
287	      ...unit,
288	      otdCad: otdBreakdown.total,
289	      otdBreakdown,
290	      dealScore: score,
291	      dealScoreBreakdown: breakdown,
292	      applicableIncentives: applicable,
293	    } satisfies ScoredUnit;
294	  });
295	
296	  return { units: scored, dealers, dealerById, incentives, buyerProvince: buyerProvince ?? null };
297	}
